package faker.data;

import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import static faker.data.GenerationBatchTest.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class GenerationPreviewTest {
    static final Path DIR=GenerationBatchTest.directory();
    @Autowired TestRestTemplate http;
    @Autowired JdbcTemplate ledger;
    JdbcTemplate target;Map<String,Object> source;
    @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("faker.data-dir",DIR::toString);}
    @BeforeEach void setup(){String url="jdbc:h2:mem:preview_"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";source=m("type","MYSQL","url",url,"username","sa","password","fixture");target=new JdbcTemplate(new DriverManagerDataSource(url,"sa","fixture"));target.execute("CREATE TABLE preview_rows(id BIGINT AUTO_INCREMENT PRIMARY KEY,label VARCHAR(30),payload BLOB)");target.execute("CREATE TABLE preview_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY)");target.execute("CREATE TRIGGER preview_insert_hook BEFORE INSERT ON preview_rows FOR EACH ROW CALL \"faker.data.GenerationPreviewTest$InsertCounter\"");InsertCounter.calls=0;}
    Map<String,Object> body(List<Map<String,Object>> tables){return m("dataSource",source,"tables",tables,"rowsPerTable",3);}
    @SuppressWarnings("unchecked") @Test void ordinaryPreviewNeverInsertsOrConsumesIdentityAndCreatesNoTasks(){
        Map<String,Object> table=table("preview_rows",100,fixed("label","java.lang.String","preview"));int before=ledger.queryForObject("SELECT COUNT(*) FROM faker_task",Integer.class);Map response=http.postForObject("/generation/preview",body(Arrays.asList(table)),Map.class);assertEquals(0,response.get("code"),response.toString());Map data=(Map)response.get("data");assertEquals("GENERATED_SAMPLE_NO_TARGET_WRITES",data.get("scope"));assertEquals(true,data.get("sampleValid"));Map sample=(Map)((List)data.get("tables")).get(0);assertEquals(3,((List)sample.get("rows")).size());assertEquals(100,sample.get("requestedRows"));
        assertEquals(0,InsertCounter.calls);assertEquals(0,target.queryForObject("SELECT COUNT(*) FROM preview_rows",Integer.class));assertEquals(before,ledger.queryForObject("SELECT COUNT(*) FROM faker_task",Integer.class));target.update("INSERT INTO preview_rows(label) VALUES('after')");assertEquals(1,target.queryForObject("SELECT id FROM preview_rows",Integer.class));
    }
    @Test void fieldExtensionsAreOmittedWithoutLaunchingTrustedCode(){Map<String,Object> table=table("preview_rows",1,col("payload","byte[]",m("code","EXT.FIELD","extension","not-installed")));Map response=http.postForObject("/generation/preview",body(Arrays.asList(table)),Map.class);assertEquals(0,response.get("code"),response.toString());assertTrue(response.toString().contains("EXTENSION_NOT_EXECUTED"),response.toString());assertFalse(Files.exists(DIR.resolve("field-extension-jobs")));assertEquals(0,InsertCounter.calls);}
    @Test void javaExpressionsCannotRunDuringReadOnlyPreview(){System.clearProperty("faker.preview.unsafe");try{Map<String,Object> table=table("preview_rows",1,col("label","java.lang.String",m("code","COND.EXPR","condition","T(java.lang.System).setProperty('faker.preview.unsafe','executed') == null","onTrue",Arrays.asList(m("code","FIX.UUID")))));Map response=http.postForObject("/generation/preview",body(Arrays.asList(table)),Map.class);assertNotEquals(0,response.get("code"),response.toString());assertNull(System.getProperty("faker.preview.unsafe"));assertTrue(response.toString().contains("PREVIEW_EXPRESSION_UNSUPPORTED"),response.toString());}finally{System.clearProperty("faker.preview.unsafe");}}
    @SuppressWarnings("unchecked") @Test void invalidNestedRulesHaveExactFieldAndRulePath(){Map<String,Object> table=table("preview_rows",1,col("label","java.lang.String",m("code","COND.EXPR","condition","true","onTrue",Arrays.asList(m("code","REG.RANGE_NUM","minSize",20,"maxSize",10)))));Map response=http.postForObject("/generation/validate",m("tables",Arrays.asList(table)),Map.class);assertNotEquals(0,response.get("code"));Map detail=(Map)response.get("diagnostic");assertNotNull(detail,response.toString());assertEquals("preview_rows",detail.get("table"));assertEquals("label",detail.get("column"));assertEquals("regs[0].onTrue[0]",detail.get("rulePath"));assertEquals("REG.RANGE_NUM",detail.get("ruleCode"));assertFalse(detail.containsKey("value"));}
    @SuppressWarnings("unchecked") @Test void runtimeFieldDiagnosticsSurviveAsyncWrappingAndRepeatedReads() throws Exception {
        Map<String,Object> sourceTable=table("preview_sources",1,fixed("id","java.lang.String","known"),fixed("role","java.lang.String","OTHER"));target.execute("CREATE TABLE preview_sources(id VARCHAR(36) PRIMARY KEY,role VARCHAR(20))");
        Map<String,Object> child=table("preview_rows",1,col("label","java.lang.String",m("code","REF.OTHER_TABLE","refOtherTableColumn",Arrays.asList("preview_sources","id"),"refMatch",m("role",m("value","REQUIRED")))));Map response=http.postForObject("/publish/task/GEN_DATA",m("dataSource",source,"tables",Arrays.asList(child,sourceTable)),Map.class);assertEquals(0,response.get("code"));String id=(String)response.get("data");Map state=null;
        for(int index=0;index<200;index++){state=(Map)http.getForObject("/asyncTask/queryProcess/"+id,Map.class).get("data");if("ERROR".equals(state.get("state")))break;Thread.sleep(25);}assertEquals("ERROR",state.get("state"));Map detail=(Map)state.get("diagnostic");assertNotNull(detail,state.toString());assertEquals("REF_MATCH_NONE",detail.get("code"));assertEquals("preview_rows",detail.get("table"));assertEquals("label",detail.get("column"));assertEquals("regs[0]",detail.get("rulePath"));assertEquals(0,detail.get("rowIndex"));assertEquals(detail,((Map)http.getForObject("/asyncTask/queryProcess/"+id,Map.class).get("data")).get("diagnostic"));assertEquals(0,target.queryForObject("SELECT COUNT(*) FROM preview_sources",Integer.class));
    }
    @Test void ordinaryConditionsUseOnlyReviewedBuiltinFunctions(){Map<String,Object> table=table("preview_rows",1,col("label","java.lang.String",m("code","COND.EXPR","condition","contains('fixture','fix')","onTrue",Arrays.asList(m("code","RES.INPUTAREA","inputs",Arrays.asList(m("value","yes","weight",1)))))));Map response=http.postForObject("/generation/preview",body(Arrays.asList(table)),Map.class);assertEquals(0,response.get("code"),response.toString());assertTrue(response.toString().contains("yes"));assertEquals(0,InsertCounter.calls);}
    @Test void previewRedactsCredentialFieldsAndRejectsUnboundedExpansion(){target.execute("ALTER TABLE preview_rows ADD COLUMN password VARCHAR(50)");Map table=table("preview_rows",1,fixed("password","java.lang.String","do-not-publish-fixture"));Map response=http.postForObject("/generation/preview",body(Arrays.asList(table)),Map.class);assertEquals(0,response.get("code"),response.toString());assertFalse(response.toString().contains("do-not-publish-fixture"));assertTrue(response.toString().contains("CREDENTIAL_REDACTED"));Map parent=table("preview_parent",2,col("id","java.lang.String",m("code","FIX.UUID")));target.execute("CREATE TABLE preview_parent(id VARCHAR(36) PRIMARY KEY)");Map child=table("preview_rows",0,fixed("label","java.lang.String","value"));child.put("parentRows",m("table","preview_parent","rowsPerParent",10000));response=http.postForObject("/generation/preview",body(Arrays.asList(parent,child)),Map.class);assertNotEquals(0,response.get("code"));assertEquals(0,InsertCounter.calls);}
    public static class InsertCounter implements org.h2.api.Trigger {static int calls;public void init(java.sql.Connection c,String schema,String trigger,String table,boolean before,int type){}public void fire(java.sql.Connection c,Object[] old,Object[] row){calls++;}public void close(){}public void remove(){}}
}
